def decode_milestone_envelope(envelope):
    need(type(envelope)is dict and set(envelope)=={'schema','encoding','expanded_bytes','expanded_sha256',
        'compressed_bytes','compressed_sha256','payload_base64'}, 'exact V4 lossless envelope fields')
    need(envelope['schema']=='unit-row-engine-milestone-lossless-envelope-v1'
         and envelope['encoding']=='zlib+base64'
         and type(envelope['expanded_bytes'])is int and 21<=envelope['expanded_bytes']<=LOSSLESS_EXPANDED_MAX_BYTES
         and type(envelope['compressed_bytes'])is int and 0<envelope['compressed_bytes']<=MILESTONE_JOURNAL_MAX_BYTES
         and type(envelope['expanded_sha256'])is str and type(envelope['compressed_sha256'])is str
         and type(envelope['payload_base64'])is str, 'literal V4 lossless envelope bounds')
    encoded=json.dumps(envelope,ensure_ascii=True,separators=(',', ':'),allow_nan=False).encode('ascii')
    need(len(encoded)<=MILESTONE_JOURNAL_MAX_BYTES, 'whole V4 encoded envelope cap')
    compressed=base64.b64decode(envelope['payload_base64'],validate=True)
    need(len(compressed)==envelope['compressed_bytes']
         and raw_pin(compressed)['sha256']==envelope['compressed_sha256'], 'V4 whole compressed hash and length')
    decoder=zlib.decompressobj();expanded=decoder.decompress(compressed,LOSSLESS_EXPANDED_MAX_BYTES+1)
    need(len(expanded)<=LOSSLESS_EXPANDED_MAX_BYTES and decoder.eof
         and decoder.unused_data==b'' and decoder.unconsumed_tail==b'', 'V4 bounded whole zlib EOF no extra stream')
    need(len(expanded)==envelope['expanded_bytes'] and raw_pin(expanded)['sha256']==envelope['expanded_sha256'],
         'V4 whole expanded hash and length')
    slots=decode(expanded)
    need(type(slots)is list and len(slots)==4, 'V4 fixed four decoded journal slots')
    need(json.dumps(slots,ensure_ascii=True,separators=(',', ':'),allow_nan=False).encode('ascii')==expanded,
         'V4 exact insertion-order ASCII expanded JSON without extra LF')
    # Exact writer structural limits, per whole wrapper rather than only record body.
    for wrapper in slots:
        if wrapper is None:continue
        pending=[(wrapper,0)];nodes=0
        while pending:
            item,depth=pending.pop();nodes+=1;kind=type(item)
            need(nodes<=200000 and depth<=128, 'V4 per-record node and depth limits')
            if item is None or kind is bool:continue
            if kind is int:need(item.bit_length()<=4096, 'V4 integer bit limit')
            elif kind is str:need(len(item)<=262144, 'V4 string length limit')
            elif kind is list:pending.extend((value,depth+1)for value in item)
            elif kind is dict:
                need(all(type(key)is str for key in item), 'V4 builtin string dictionary keys')
                for key,value in item.items():pending.extend(((key,depth+1),(value,depth+1)))
            else:need(False, 'V4 builtin JSON value types only')
    return slots,expanded,len(encoded)


